 Variable Domains Available domains are represented by the  BoolDomain  and  SpinDomain  types, respectively,  $x \in \mathbb{B} = \lbrace 0, 1 \rbrace$  and  $s \in \mathbb{S} = \lbrace -1, 1 \rbrace$ . Conversion between domains follows the identity: \[\left\lbrace\begin{align*}
    s &= 2x - 1          \\
    x &= \frac{s + 1}{2}
\end{align*}\right.\]

 Model Backend using QUBOTools

mutable struct SuperModel{V,T,U} <: QUBOTools.AbstractModel{V,T,U}
    model::QUBOTools.Model{V,T,U}
    super::Bool

    function SuperModel{V,T,U}() where {V,T,U}
        return new(QUBOTools.Model{V,T,U}(), true)
    end
end

QUBOTools.backend(model::SuperModel) = model.model model = SuperModel{Symbol,Float64,Int}() QUBOTools Model
